const options = {
  hostname: 'localhost',
  port: 3000,
  path: '/api/ai/article-chat',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(data),
    'X-Smoke-Test': 'true'
  }
};

const req = http.request(options, (res) => {
  let output = '';
  res.on('data', (chunk) => {
    output += chunk.toString();
  });
  res.on('end', () => {
    console.log("RESPONSE ENDED. OUTPUT:");
    console.log(output);
  });
});

req.on('error', (e) => {
  console.error(`Problem with request: ${e.message}`);
});

req.write(data);
req.end();

