"use client"

import { usePathname } from "next/navigation"
import type { CSSProperties, FormEvent, ReactNode } from "react"
import { useEffect, useRef, useState } from "react"
import { useAuthGate, useSession } from "@/context/AuthGateContext"

interface Message {
  role: "user" | "assistant"
  content: string
  lowConfidence?: boolean
  warning?: string
}

type StreamEvent = {
  type?: string
  content?: string
  lowConfidence?: boolean
  warning?: string
  contextStats?: {
    lowConfidence?: boolean
    warning?: string
  }
}

function canUseHover() {
  return (
    typeof window !== "undefined" &&
    window.matchMedia("(hover: hover) and (pointer: fine)").matches
  )
}

function formatAIResponse(content: string): ReactNode {
  const lines = content.split("\n")
  const elements: ReactNode[] = []
  let bulletBuffer: string[] = []

  const flushBullets = () => {
    if (bulletBuffer.length === 0) return
    elements.push(
      <ul key={`ul-${elements.length}`} style={formattedListStyle}>
        {bulletBuffer.map((item, index) => (
          <li key={index} style={formattedListItemStyle}>
            <span style={formattedBulletStyle}>◆</span>
            <span>{item}</span>
          </li>
        ))}
      </ul>
    )
    bulletBuffer = []
  }

  for (const line of lines) {
    const trimmed = line.trim()
    const bulletMatch =
      trimmed.match(/^[*\-•]\s+(.+)/) ||
      trimmed.match(/^\d+\.\s+(.+)/)

    if (bulletMatch) {
      bulletBuffer.push(bulletMatch[1])
      continue
    }

    flushBullets()

    if (trimmed.length > 0) {
      const isLabel = trimmed.endsWith(":")
      elements.push(
        <p
          key={`p-${elements.length}`}
          style={{
            ...formattedParagraphStyle,
            color: isLabel ? "var(--text-dim)" : "var(--text)",
            fontWeight: isLabel ? 500 : 400,
            letterSpacing: isLabel ? "0.3px" : 0,
          }}
        >
          {trimmed}
        </p>
      )
    }
  }

  flushBullets()
  return <>{elements}</>
}

void formatAIResponse

function formatReadableAIResponse(content: string): ReactNode {
  const elements: ReactNode[] = []
  let bullets: string[] = []

  const flushBullets = () => {
    if (bullets.length === 0) return
    elements.push(
      <ul key={`clean-ul-${elements.length}`} style={formattedListStyle}>
        {bullets.map((item, index) => (
          <li key={index} style={formattedListItemStyle}>
            <span style={formattedBulletStyle}>◆</span>
            <span>{item}</span>
          </li>
        ))}
      </ul>
    )
    bullets = []
  }

  for (const line of content.split("\n")) {
    const trimmed = line.trim()
    const bulletMatch =
      trimmed.match(/^[*\-•]\s+(.+)/) ||
      trimmed.match(/^\d+\.\s+(.+)/)

    if (bulletMatch) {
      bullets.push(bulletMatch[1])
      continue
    }

    flushBullets()

    if (trimmed.length > 0) {
      const isLabel = trimmed.endsWith(":")
      elements.push(
        <p
          key={`clean-p-${elements.length}`}
          style={{
            ...formattedParagraphStyle,
            color: isLabel ? "var(--text-dim)" : "var(--text)",
            fontWeight: isLabel ? 500 : 400,
            letterSpacing: isLabel ? "0.3px" : 0,
          }}
        >
          {trimmed}
        </p>
      )
    }
  }

  flushBullets()
  return <>{elements}</>
}

export default function ChatAssistant() {
  const pathname = usePathname()
  const [isOpen, setIsOpen] = useState(false)
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "assistant",
      content: "Hi! I'm your LivePulse AI. Ask me anything about today's news.",
    },
  ])
  const [input, setInput] = useState("")
  const [isTyping, setIsTyping] = useState(false)
  const [isThinking, setIsThinking] = useState(false)
  const [streamingContent, setStreamingContent] = useState("")
  const scrollRef = useRef<HTMLDivElement>(null)
  const lastTouchActivationAt = useRef(0)
  const currentTopic = pathname.startsWith("/topic/")
    ? pathname.split("/topic/")[1].split("/")[0]
    : "all"
  const articleIdMatch = pathname.match(/^\/news\/([^/]+)/)
  const currentArticleId = articleIdMatch ? articleIdMatch[1] : undefined

  const { triggerAuthGate } = useAuthGate()
  const { hasSession } = useSession()

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [messages, streamingContent])

  async function handleSend(event: FormEvent) {
    event.preventDefault()
    if (!input.trim() || isTyping) return

    const userMsg = input
    const maxHistory = 20
    const trimmedHistory = messages.slice(-maxHistory)
    const nextMessages: Message[] = [
      ...trimmedHistory,
      { role: "user", content: userMsg },
    ]

    if (!hasSession) {
      triggerAuthGate('chat')
      return
    }

    setInput("")
    setMessages(nextMessages)
    setIsTyping(true)
    setIsThinking(true)
    setStreamingContent("")

    try {
      const endpoint = currentArticleId ? "/api/ai/article-chat" : "/api/ai/chat"
      const payload = currentArticleId
        ? { messages: nextMessages, articleId: currentArticleId, topic: currentTopic }
        : { messages: nextMessages, topic: currentTopic }

      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      })

      if (response.status === 401) {
        setMessages(trimmedHistory)
        triggerAuthGate('chat')
        setIsTyping(false)
        setIsThinking(false)
        return
      }

      if (!response.ok || !response.body) {
        throw new Error("Chat failed")
      }

      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let accumulated = ""
      let buffer = ""

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        const events = buffer.split("\n\n")
        buffer = events.pop() ?? ""

        for (const rawEvent of events) {
          const line = rawEvent
            .split("\n")
            .find((eventLine) => eventLine.startsWith("data: "))
          if (!line) continue

          try {
            const event = JSON.parse(line.slice(6)) as StreamEvent

            if (event.type === "start") {
              setIsThinking(false)
            }

            if (event.type === "token" && typeof event.content === "string") {
              accumulated += event.content
              setStreamingContent(accumulated)
            }

            if (event.type === "done") {
              const finalContent =
                typeof event.content === "string" ? event.content : accumulated
              setStreamingContent("")
              setMessages((prev) => [
                ...prev,
                {
                  role: "assistant",
                  content: finalContent || "No response available.",
                  lowConfidence:
                    event.lowConfidence === true ||
                    event.contextStats?.lowConfidence === true,
                  warning:
                    event.warning ||
                    event.contextStats?.warning ||
                    "Limited sources available. This answer may be incomplete.",
                },
              ])
            }

            if (event.type === "error") {
              setStreamingContent("")
              setMessages((prev) => [
                ...prev,
                {
                  role: "assistant",
                  content:
                    event.content ||
                    "AI service is unavailable right now. Try again when Ollama is running.",
                },
              ])
            }
          } catch {
            // Ignore malformed SSE frames.
          }
        }
      }
    } catch (error) {
      console.error(error)
      setStreamingContent("")
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: "AI service is unavailable right now. Try again when Ollama is running.",
        },
      ])
    } finally {
      setIsTyping(false)
      setIsThinking(false)
      setStreamingContent("")
    }
  }

  const sendDisabled = !input.trim() || isTyping

  function toggleChat() {
    setIsOpen((value) => !value)
  }

  function handleLauncherClick() {
    toggleChat()
  }

  return (
    <>
      <button
        className="chat-launcher"
        onClick={handleLauncherClick}
        style={floatingButtonStyle}
      >
        {isOpen ? "x" : "AI"}
      </button>

      {isOpen && (
        <div className="chat-panel-open" style={windowStyle}>
          <div style={headerStyle}>
            <div style={statusDotStyle} />
            <div style={{ flex: 1 }}>
              <div style={titleStyle}>LivePulse AI</div>
              <div style={subtitleStyle}>Online - Context-Aware</div>
            </div>
          </div>

          <div ref={scrollRef} className="chat-messages" style={messagesStyle}>
            {messages.map((message, index) => (
              <div
                key={`${message.role}-${index}`}
                style={{
                  ...messageBubbleBaseStyle,
                  alignSelf: message.role === "user" ? "flex-end" : "flex-start",
                  maxWidth: message.role === "user" ? "80%" : "86%",
                  padding: message.role === "user" ? "12px 16px" : "14px 18px",
                  borderRadius:
                    message.role === "user" ? "8px 0 8px 8px" : "0 8px 8px 8px",
                  background:
                    message.role === "user"
                      ? "rgba(108, 143, 255, 0.1)"
                      : "var(--surface2)",
                  border:
                    message.role === "user"
                      ? "1px solid rgba(108, 143, 255, 0.2)"
                      : "1px solid var(--border2)",
                  borderLeft:
                    message.role === "user"
                      ? "1px solid rgba(108, 143, 255, 0.2)"
                      : "3px solid var(--accent)",
                }}
              >
                {message.role === "assistant"
                  ? formatReadableAIResponse(message.content)
                  : message.content}
                {message.role === "assistant" && message.lowConfidence && (
                  <div style={warningBadgeStyle}>
                    <span>!</span>
                    <span>{message.warning}</span>
                  </div>
                )}
              </div>
            ))}
            {isThinking && (
              <div style={thinkingRowStyle}>
                <div style={thinkingBubbleStyle}>
                  {[0, 1, 2].map((i) => (
                    <span
                      key={i}
                      style={{
                        ...thinkingDotStyle,
                        animationDelay: `${i * 0.2}s`,
                      }}
                    />
                  ))}
                  <span style={thinkingTextStyle}>AI is thinking...</span>
                </div>
              </div>
            )}

            {streamingContent && (
              <div style={streamingBubbleStyle}>
                {formatReadableAIResponse(streamingContent)}
                <span style={streamingCursorStyle} />
              </div>
            )}
          </div>

          <form onSubmit={handleSend} style={formOuterStyle}>
            <div
              style={inputShellStyle}
              onFocus={(event) => {
                event.currentTarget.style.border = "1px solid rgba(108,143,255,0.4)"
                event.currentTarget.style.background = "var(--surface)"
              }}
              onBlur={(event) => {
                event.currentTarget.style.border = "1px solid var(--border2)"
                event.currentTarget.style.background = "var(--surface2)"
              }}
            >
              <input
                value={input}
                onChange={(event) => setInput(event.target.value)}
                disabled={isTyping}
                placeholder="Ask about today's news..."
                style={inputStyle}
              />
              <button
                type="submit"
                disabled={sendDisabled}
                style={{
                  ...askButtonStyle,
                  opacity: sendDisabled ? 0.4 : 1,
                  cursor: sendDisabled ? "not-allowed" : "pointer",
                }}
              >
                ASK
              </button>
            </div>
          </form>
        </div>
      )}

      <style jsx>{`
        @keyframes slideIn {
          from {
            opacity: 0;
            transform: translateY(20px) scale(0.95);
          }
          to {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
        }
        @media (hover: hover) {
          .chat-launcher:hover {
            transform: scale(1.1) !important;
          }
        }
      `}</style>
    </>
  )
}

